import {Engine,WORLDS,W,H} from './engine.mjs';
const $=s=>document.querySelector(s),canvas=$('#game'),ctx=canvas.getContext('2d');ctx.imageSmoothingEnabled=false;
const engine=new Engine(),images={};let loaded=false,paused=false,keys={},touch={},last=0,accumulator=0,toastTime=0,started=false,helpWasPaused=false,soundChosen=false;
let saved=0;try{saved=Math.max(0,Math.min(31,Number(localStorage.getItem('pixelquest-course'))||0));}catch{}
if(saved>0){$('#continue').hidden=false;$('#continue').textContent=`つづきから  ${Math.floor(saved/4)+1}-${saved%4+1}`;}
function loadImage(name){return new Promise(resolve=>{const im=new Image();im.onload=()=>{images[name]=im;resolve();};im.onerror=()=>{$('#overlay-text').textContent='画像を読み込めませんでした。ページを再読み込みしてください。';resolve();};im.src=`assets/${name}.png`;});}
Promise.all(['tiles','characters','backgrounds'].map(loadImage)).then(()=>{loaded=Object.keys(images).length===3;});
function sprite(id,x,y,w=18,h=18){if(!images.tiles)return;ctx.drawImage(images.tiles,(id%20)*18,Math.floor(id/20)*18,18,18,Math.round(x),Math.round(y),w,h);}
function character(col,row,x,y,w=24,h=24,flip=false){if(!images.characters)return;ctx.save();ctx.translate(Math.round(x)+(flip?w:0),Math.round(y));if(flip)ctx.scale(-1,1);ctx.drawImage(images.characters,col*24,row*24,24,24,0,0,w,h);ctx.restore();}
function text(t,x,y,color='#fff',size=8,align='left'){ctx.fillStyle=color;ctx.font=`${size}px "Press Start 2P", monospace`;ctx.textAlign=align;ctx.fillText(t,Math.round(x),Math.round(y));ctx.textAlign='left';}
function background(){const l=engine.level,cam=engine.camera;const dark=l.type==='castle'||l.type==='underground'||l.type==='bonus',night=l.world===1||l.world===6;ctx.fillStyle=dark?'#101a2a':l.type==='water'?'#2674ae':night?'#273651':l.world===4?'#c4e5f0':'#bfeff0';ctx.fillRect(0,0,W,H);
 if(!dark&&l.type!=='water'&&images.backgrounds){const bgCol=l.world===5?4:l.world===4?0:6;const offset=(cam*.18)%96;for(let x=-96;x<W+96;x+=96){ctx.globalAlpha=night?.35:1;ctx.drawImage(images.backgrounds,bgCol*24,24,24,24,Math.round(x-offset),75,96,96);ctx.drawImage(images.backgrounds,bgCol*24,48,24,24,Math.round(x-offset),171,96,45);ctx.globalAlpha=1;}for(let i=0;i<6;i++){const cx=((i*99-cam*.1)%(W+100)+W+100)%(W+100)-50,cy=23+(i%3)*14;for(let j=0;j<3;j++)sprite(153+j,cx+j*18,cy);}}
 if(night||dark){for(let i=0;i<35;i++){const x=((i*71+17-cam*.05)%W+W)%W,y=(i*29)%100+7;ctx.fillStyle=i%4?'#b6cbd060':'#f6cc65';ctx.fillRect(Math.floor(x),y,1,i%4?1:2);}}
 if(dark){for(let x=0;x<W/36+1;x++)for(let y=1;y<5;y++){ctx.strokeStyle=l.type==='castle'?'#263046':'#233347';ctx.strokeRect(Math.floor(x*36-cam*.1%36)+(y%2?18:0),y*36,35,35);}}
 if(l.type==='water'){ctx.fillStyle='#90e1eb';ctx.fillRect(0,8,W,2);for(let i=0;i<12;i++){const bx=(i*47+9)%W,by=180-(engine.tick*.18+i*21)%165;ctx.strokeStyle='#c4f1f15c';ctx.strokeRect(bx,by,2+(i%3),2+(i%3));}}
}
function draw(){if(!loaded)return;background();const l=engine.level,cam=engine.camera,world=l.world;ctx.save();ctx.translate(-Math.floor(cam),0);
 const x0=Math.max(0,Math.floor(cam/18)-1),x1=Math.min(l.cols-1,Math.ceil((cam+W)/18)+1);
 if(!['castle','underground','bonus','water'].includes(l.type)){for(const d of l.decor)if(d.type==='tree'&&d.x>cam-60&&d.x<cam+W+60){sprite(127,d.x,144,18,36);sprite(125,d.x+20,155,18,25);}}
 for(let y=0;y<12;y++)for(let x=x0;x<=x1;x++){const b=l.map[y][x];if(!b?.type||b.type==='pipe')continue;let id=0;switch(b.type){case'ground':id=world===4?80:['castle','underground','bonus'].includes(l.type)?29:0;break;case'dirt':id=['castle','underground','bonus'].includes(l.type)?130:4;break;case'brick':id=6;break;case'question':id=engine.tick%60<30?10:11;break;case'used':id=29;break;case'stone':id=['castle','underground'].includes(l.type)?130:47;break;case'lava':id=12+Math.floor(engine.tick/10)%4;break;case'bridge':id=91;break;case'platform':id=147;break;}sprite(id,x*18,y*18-(b.bump?Math.sin(b.bump/8*Math.PI)*4:0));}
 for(const d of l.decor){if(d.x<cam-60||d.x>cam+W+80)continue;if(d.type==='pipe'){sprite(93,d.x,d.y);sprite(94,d.x+18,d.y);for(let y=d.y+18;y<180;y+=18){sprite(113,d.x,y);sprite(114,d.x+18,y);}if(d.secret)text('↓',d.x+18,d.y-7,'#fff5bf',10,'center');}if(d.type==='firebar'){sprite(151,d.x-9,d.y-9);const angle=engine.tick*.025+d.phase;for(let i=1;i<=d.count;i++)sprite(151,d.x+Math.cos(angle)*i*10-5,d.y+Math.sin(angle)*i*10-5,10,10);}if(d.type==='lever'){sprite(engine.state==='clear'?66:64,d.x,d.y+8);text('EXIT',d.x+8,d.y-2,'#f6cc65',6,'center');}}
 for(const p of l.platforms)for(let x=0;x<p.w;x+=18)sprite(147,p.x+x,p.y-4,18,12);
 for(const c of l.coins)if(c.alive)sprite(engine.tick%40<20?151:152,c.x-3,c.y-3,14,14);
 for(const i of engine.items)if(i.alive)sprite(i.kind==='growth'?128:i.kind==='fire'?145:i.kind==='life'?44:67,i.x-2,i.y-2,18,18);
 for(const e of l.enemies){if(!e.alive||e.x<cam-60||e.x>cam+W+60)continue;const frame=Math.floor(engine.tick/12)%2;switch(e.type){case'walker':character(2+frame,1,e.x-5,e.y-8);break;case'shell':character(frame,2,e.x-5,e.y-8);break;case'idleShell':case'kicked':character(2,2,e.x-5,e.y-13);break;case'fish':character(6+frame,2,e.x-5,e.y-7);break;case'fly':character(7+frame,2,e.x-5,e.y-7);break;case'plant':sprite(127,e.x-3,e.y-3,18,24);break;case'lava':sprite(151,e.x-3,e.y-3,16,16);break;case'boss':character(3+frame,2,e.x-6,e.y-10,48,48);break;}}
 for(const s of engine.shots)sprite(151,s.x-2,s.y-2,s.enemy?16:10,s.enemy?10:10);
 const p=engine.player;if(p.invincible===0||Math.floor(engine.tick/5)%2||engine.state==='clear'){let col=p.power===2?0:6;if(p.star>0)col=Math.floor(engine.tick/5)%4*2;const anim=Math.abs(p.vx)>.1&&p.grounded?Math.floor(engine.tick/8)%2:0;character(col+anim,0,p.x-5,p.y-(p.power?9:7),24,p.power?36:24,p.facing<0);}
 if(l.type!=='castle'&&l.type!=='bonus'){const fx=l.exit;ctx.fillStyle='#e8edf5';ctx.fillRect(fx,38,2,142);sprite(151,fx-4,30,10,10);sprite(112,fx+2,engine.state==='clear'?Math.min(155,42+engine.phase*2):42,18,18);for(let y=0;y<3;y++)for(let x=0;x<4;x++)sprite(130,fx+48+x*18,126+y*18);sprite(132,fx+65,148,36,36);text(`${world+1}`,fx+84,142,'#f6cc65',8,'center');}
 for(const q of engine.particles){if(q.text)text(q.text,q.x,q.y,'#fff6c8',6);else{ctx.fillStyle=q.color;ctx.fillRect(q.x,q.y,4,4);}}ctx.restore();if(l.type==='water'){ctx.fillStyle='#58c9ed14';ctx.fillRect(0,0,W,H);}if(engine.state==='clear')text(l.type==='castle'?'CITADEL CLEAR!':'COURSE CLEAR!',W/2,62,'#fff6cd',10,'center');if(paused){ctx.fillStyle='#09142799';ctx.fillRect(0,0,W,H);text('PAUSED',W/2,H/2,'#fff6cd',16,'center');text('P / ESC TO RESUME',W/2,H/2+23,'#fff',7,'center');}}
class Audio{
 constructor(){this.on=false;this.ctx=null;this.step=0;this.next=0;this.melody=[72,0,76,79,76,72,67,69,72,0,74,77,74,69,65,67,72,76,79,84,79,76,72,67,69,72,74,77,76,72,67,0];}
 init(){try{this.ctx??=new(window.AudioContext||window.webkitAudioContext)();this.ctx.resume();}catch{this.on=false;}}
 note(midi,delay=0,duration=.09,volume=.025,type='square'){if(!this.on||!this.ctx||!midi)return;const osc=this.ctx.createOscillator(),gain=this.ctx.createGain(),t=this.ctx.currentTime+delay;osc.type=type;osc.frequency.value=440*Math.pow(2,(midi-69)/12);gain.gain.setValueAtTime(volume,t);gain.gain.exponentialRampToValueAtTime(.001,t+duration);osc.connect(gain);gain.connect(this.ctx.destination);osc.start(t);osc.stop(t+duration+.02);}
 sound(kind){const tunes={jump:[60,67],coin:[83,88],stomp:[47,35],kick:[50,38],bump:[43],break:[48,36,31],fire:[76,52],power:[60,64,67,72,76],star:[76,79,84],life:[72,76,79,84],hurt:[66,60,53],death:[72,69,65,60,55,48],clear:[60,64,67,72,76,79,84],warp:[72,67,60],checkpoint:[79,84],won:[60,67,72,76,79,84,88]};(tunes[kind]||[]).forEach((n,i)=>this.note(n,i*.085,.12,.04));}
 update(){if(!this.on||!this.ctx||paused||engine.state!=='playing')return;if(this.ctx.currentTime>=this.next){const underground=['castle','underground','bonus'].includes(engine.level.type),shift=underground?-12:0,fast=engine.time<100||engine.player.star>0;this.note(this.melody[this.step%32]?this.melody[this.step%32]+shift:0,0,.12,.014,'square');if(this.step%2===0)this.note([48,48,53,55][Math.floor(this.step/8)%4]+shift,0,.19,.019,'triangle');this.step++;this.next=this.ctx.currentTime+(fast?.11:.17);}}
}
const audio=new Audio();
function updateHud(){const s=engine.snapshot();$('#pause').textContent=paused?'▶':'Ⅱ';$('#pause').setAttribute('aria-label',paused?'再開':'一時停止');$('#score').textContent=String(s.score).padStart(6,'0');$('#coins').textContent=`× ${String(s.coins).padStart(2,'0')}`;$('#lives').textContent=`× ${String(s.lives).padStart(2,'0')}`;$('#time').textContent=String(s.time).padStart(3,'0');$('#world').textContent=`${s.world} - ${s.course}`;$('#level-name').textContent=WORLDS[s.world-1];$('#status').textContent=paused?'PAUSED':engine.state==='title'?'READY TO PLAY':s.area==='bonus'?'SECRET ROOM':engine.player.star>0?'INVINCIBLE':engine.player.power===2?'FIRE POWER':engine.state==='clear'?'COURSE CLEAR':engine.state==='dying'?'TRY AGAIN':engine.state==='gameover'?'GAME OVER':engine.state==='won'?'ALL WORLDS CLEAR':'ADVENTURE IN PROGRESS';}
function announce(message){$('#toast').textContent=message;toastTime=120;}
function consume(){for(const e of engine.events){audio.sound(e.type);if(e.type==='progress'){saved=e.index;try{localStorage.setItem('pixelquest-course',String(saved));}catch{}}if(e.type==='level'&&started){announce(`WORLD ${Math.floor(engine.index/4)+1}-${engine.index%4+1}`);audio.step=0;}if(e.type==='checkpoint')announce('CHECKPOINT');if(e.type==='life')announce('1 UP!');if(e.type==='power')announce(engine.player.power===2?'FIRE POWER!':'POWER UP!');if(e.type==='star')announce('INVINCIBLE!');if(e.type==='warp')announce('SECRET PASSAGE');if(e.type==='gameover'||e.type==='won')showEnd(e.type==='won');}engine.events=[];}
function showEnd(won){$('#overlay').hidden=false;$('#overlay .eyebrow').textContent=won?'ALL 32 COURSES CLEARED':'ANOTHER ADVENTURE AWAITS';$('#overlay h1').innerHTML=won?'QUEST<br><em>COMPLETE</em>':'GAME<br><em>OVER</em>';$('#overlay-text').textContent=won?`星の世界に平和が戻りました。SCORE ${engine.score}`:`WORLD ${Math.floor(engine.index/4)+1}-${engine.index%4+1} / SCORE ${engine.score}`;$('#start').innerHTML=won?'もう一度あそぶ <span>ENTER</span>':'このコースから再挑戦 <span>ENTER</span>';$('#continue').hidden=true;}
function start(index=0){if(!loaded)return;started=true;paused=false;keys={};touch={};$('#overlay').hidden=true;$('#toast').textContent='';engine.start(index);audio.init();if(!audio.on&&!soundChosen){audio.on=true;$('#sound').textContent='音 ON';$('#sound').setAttribute('aria-label','音をオフにする');}consume();canvas.focus({preventScroll:true});}
$('#start').addEventListener('click',()=>start(engine.state==='gameover'?engine.index:0));$('#continue').addEventListener('click',()=>start(saved));
function togglePause(){if(!started||!['playing','dying','clear'].includes(engine.state))return;paused=!paused;keys={};touch={};$('#pause').textContent=paused?'▶':'Ⅱ';$('#pause').setAttribute('aria-label',paused?'再開':'一時停止');}
$('#pause').onclick=togglePause;$('#sound').onclick=()=>{soundChosen=true;audio.on=!audio.on;audio.init();$('#sound').textContent=audio.on?'音 ON':'音 OFF';$('#sound').setAttribute('aria-label',audio.on?'音をオフにする':'音をオンにする');};
$('#fullscreen').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await $('.screen-frame').requestFullscreen();}catch{announce('このブラウザでは全画面にできません');}};
function closeHelp(){ $('#instructions').close();paused=helpWasPaused;canvas.focus({preventScroll:true});}
$('#help').onclick=()=>{helpWasPaused=paused;if(started)paused=true;keys={};touch={};$('#instructions').showModal();};$('#close-help').onclick=closeHelp;$('#help-ok').onclick=closeHelp;$('#instructions').addEventListener('cancel',()=>{paused=helpWasPaused;});
const mapping={ArrowLeft:'left',KeyA:'left',ArrowRight:'right',KeyD:'right',ArrowDown:'down',KeyS:'down',KeyZ:'jump',Space:'jump',KeyW:'jump',ArrowUp:'jump',KeyX:'run',ShiftLeft:'run',ShiftRight:'run'};
window.addEventListener('keydown',e=>{if($('#instructions').open)return;if(e.code==='Enter'){e.preventDefault();if(engine.state==='title'||engine.state==='gameover'||engine.state==='won')start(engine.state==='gameover'?engine.index:0);else if(!e.repeat)togglePause();}if((e.code==='KeyP'||e.code==='Escape')&&!e.repeat)togglePause();if(mapping[e.code]){e.preventDefault();keys[e.code]=true;}});
window.addEventListener('keyup',e=>{keys[e.code]=false;});
function blur(){keys={};touch={};document.querySelectorAll('.touch .active').forEach(b=>b.classList.remove('active'));if(started&&engine.state==='playing')paused=true;}
window.addEventListener('blur',blur);document.addEventListener('visibilitychange',()=>{if(document.hidden)blur();});
document.querySelectorAll('[data-key]').forEach(b=>{const k=b.dataset.key;b.addEventListener('pointerdown',e=>{e.preventDefault();b.setPointerCapture(e.pointerId);touch[k]=true;b.classList.add('active');audio.init();});const release=()=>{touch[k]=false;b.classList.remove('active');};b.addEventListener('pointerup',release);b.addEventListener('pointercancel',release);b.addEventListener('lostpointercapture',release);b.addEventListener('contextmenu',e=>e.preventDefault());});
let gamepadStart=false;function input(){const out={...touch};for(const[k,v]of Object.entries(keys))if(v&&mapping[k])out[mapping[k]]=true;for(const g of navigator.getGamepads?.()||[]){if(!g)continue;out.left||=g.axes[0]<-.3||g.buttons[14]?.pressed;out.right||=g.axes[0]>.3||g.buttons[15]?.pressed;out.down||=g.axes[1]>.4||g.buttons[13]?.pressed;out.jump||=g.buttons[0]?.pressed;out.run||=g.buttons[1]?.pressed||g.buttons[2]?.pressed;const gpStart=g.buttons[9]?.pressed;if(gpStart&&!gamepadStart){if(!started)start();else togglePause();}gamepadStart=gpStart;break;}return out;}
function frame(now){const elapsed=Math.min(100,now-(last||now));last=now;accumulator+=elapsed;const controls=input();while(accumulator>=1000/60){if(!paused&&started)engine.step(controls);else if(engine.state==='title')engine.tick++;if(toastTime>0){toastTime--;if(!toastTime)$('#toast').textContent='';}accumulator-=1000/60;}consume();audio.update();draw();updateHud();requestAnimationFrame(frame);}requestAnimationFrame(frame);
function validateIndex(input){if(!input||!Number.isInteger(input.world)||!Number.isInteger(input.course)||input.world<1||input.world>8||input.course<1||input.course>4)throw new Error('world must be 1–8 and course must be 1–4');return(input.world-1)*4+input.course-1;}
const context=document.modelContext;if(context?.registerTool){const lifecycle=new AbortController();for(const tool of [{name:'read_game_state',description:'Read the current world, course, score, lives, power and progress.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({...engine.snapshot(),paused})},{name:'start_game_course',description:'Start a new game at a selected world and course, resetting score and lives.',inputSchema:{type:'object',properties:{world:{type:'integer',minimum:1,maximum:8},course:{type:'integer',minimum:1,maximum:4}},required:['world','course'],additionalProperties:false},annotations:{readOnlyHint:false},execute:args=>{const index=validateIndex(args);if(!loaded)throw new Error('Assets are loading');start(index);updateHud();return engine.snapshot();}}]){try{Promise.resolve(context.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
window.pixelQuest={getState:()=>({...engine.snapshot(),paused,loaded}),engine};
